function syncMissionActions(){for(const id of ['missionstatus','saveflighthelp','missionimportstatus','savedflightview','savedflightselect','draftstatus']){const from=el(id),to=el(id+'bottom');if(to.innerHTML!==from.innerHTML)to.innerHTML=from.innerHTML;if(id==='savedflightselect')to.value=from.value;}for(const id of ['saveflight','copyselectedmission','exportflight'])el(id+'bottom').disabled=el(id).disabled;for(const id of ['recoverdraft','dismissdraft'])el(id+'bottom').hidden=el(id).hidden;}
for(const id of ['saveflight','copycurrentmission','copyselectedmission','exportflight','recoverdraft','dismissdraft'])el(id+'bottom').onclick=()=>{el(id).click();if(id==='copyselectedmission')el('missionprefillbottom').open=false;syncMissionActions();};el('savedflightselectbottom').onchange=()=>{el('savedflightselect').value=el('savedflightselectbottom').value;el('savedflightselect').dispatchEvent(new Event('change',{bubbles:true}));syncMissionActions();};el('uploadmissionbottom').onchange=async event=>{await el('uploadmission').onchange(event);syncMissionActions();};
const missionObserver=new MutationObserver(syncMissionActions);for(const id of ['missionstatus','saveflighthelp','missionimportstatus','savedflightview','savedflightselect','saveflight','copyselectedmission','exportflight','draftstatus','recoverdraft','dismissdraft'])missionObserver.observe(el(id),{childList:true,subtree:true,characterData:true,attributes:true});window.addEventListener('flightdesk:decision',syncMissionActions);syncMissionActions();
