const steps=document.createElement('nav');steps.className='process-nav';steps.setAttribute('aria-label','Flight preparation steps');for(const[i,id]of order.entries()){const a=document.createElement('a');a.href='#'+id;a.dataset.section=id;const caption=document.createElement('span');caption.className='nav-label';caption.textContent=(i+1)+'. '+({missioncard:'Mission',sitecard:'Site & time',crewcard:'Crew',aircraftcard:'Aircraft',batterycard:'Battery',weathercard:'Weather',airspacecard:'Airspace',evidencecard:'Final review',flightcard:'Flight',postflightcard:'Post-flight'})[id];const state=document.createElement('span');state.className='nav-progress';state.setAttribute('aria-hidden','true');a.append(caption,state);steps.append(a);}for(const[id,name]of [['decisioncard','Readiness summary'],['audit','Reference & sources']]){const a=document.createElement('a');a.href='#'+id;a.textContent=name;steps.append(a);}el('navsections').append(steps);
