for(const[id,title]of Object.entries(groupTitles)){const section=el(id);if(!section)continue;const heading=section.querySelector(':scope > .cardhead h2');if(heading)heading.textContent=title;const details=document.createElement('details');details.className='field-section';details.dataset.field=id;details.open=['missioncard','sitecard','flightcard'].includes(id);const summary=document.createElement('summary');summary.textContent=title;details.append(summary);while(section.firstChild)details.append(section.firstChild);if(id==='weathercard'){const body=document.createElement('div');body.className='body weatherbody';for(const child of Array.from(details.children))if(child!==summary&&!child.classList.contains('cardhead'))body.append(child);details.append(body);}section.append(details);}
function fieldMode(on){for(const d of document.querySelectorAll('.field-section')){if(!on){d.dataset.compactOpen=String(d.open);d.open=true;}else if(d.dataset.compactOpen!==undefined)d.open=d.dataset.compactOpen==='true';}document.body.classList.toggle('fieldmode',on);el('fieldtoggle').textContent=on?'Full form view':'Compact field view';el('fieldtoggle').setAttribute('aria-pressed',String(on));try{localStorage.setItem('flightdesk-field-mode',on?'1':'0');}catch{}}
let compact=true;try{compact=localStorage.getItem('flightdesk-field-mode')!=='0';}catch{}fieldMode(compact);el('fieldtoggle').onclick=()=>fieldMode(!document.body.classList.contains('fieldmode'));
function target(reason){const t=reason.toLowerCase();const pairs=[[/launch site|location input/,'lat'],[/aircraft or custom/,'aircraftselect'],[/physical class|exact aircraft|class\/configuration/,'specconfirm'],[/open category|operation profile|class remains/,'aircraftcard'],[/mission-area radius/,'missionradius'],[/airspace:|notam|aip reference/,'airspacepanel'],[/flight date|flight start|local hour/,'flywithin30'],[/duration|full-charge flight|landing charge|minutes to keep|battery budget/,'reserve'],[/pilot profile|pilot id/,'pilotselect'],[/operator profile|operator id/,'operatorselect'],[/precipitation|visibility threshold/,'weathercard'],[/wind limit|wind ceiling|temperature range|manual\/reference|manufacturer preset|mtom/,'aircraftcard'],[/forecast|daylight|sunrise|on-site conditions/,'weathercard'],[/battery.*select|select.*battery|serviceable|inspection|battery\/set charge|packs than/,'batteryselect'],[/cell|voltage|battery replacement/,'cellpanel'],[/aid kit|fire fighting/,'firstaidready'],[/supported flight|battery\/set inspection/,'batteryconfirm'],[/ten pre-flight/,'evidencecard'],[/final.*review/,'finalconfirm']];return pairs.find(([re])=>re.test(t))?.[1]||'evidencecard';}
function refresh(result){if(result)lastResult=result;el('fieldbarstatus').dataset.readiness=lastResult.status||'no-go';el('fieldbarstatus').textContent=window.FLIGHT_ASSESSMENT.label(lastResult.status)+(lastResult.status==='no-go'?' · '+lastResult.reasons.length+' unresolved':'');}
