el('navsave').onclick=()=>{el('saveflight').click();};const saveObserver=new MutationObserver(()=>{el('navsavestatus').textContent=el('missionstatus').textContent;el('navsave').disabled=el('saveflight').disabled;});saveObserver.observe(el('missionstatus'),{childList:true,subtree:true,characterData:true});saveObserver.observe(el('saveflight'),{attributes:true,attributeFilter:['disabled']});
