const visibleSections=new Map(),activeObserver=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting)visibleSections.set(e.target.id,e.target);else visibleSections.delete(e.target.id);}const current=[...visibleSections.values()].sort((a,b)=>Math.abs(a.getBoundingClientRect().top-100)-Math.abs(b.getBoundingClientRect().top-100))[0];if(current)for(const a of steps.querySelectorAll('a')){const active=a.hash==='#'+current.id;a.classList.toggle('nav-active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}},{rootMargin:'0px 0px -45% 0px',threshold:0});for(const id of [...order,'decisioncard','audit'])activeObserver.observe(el(id));
